param([Parameter(Mandatory=$true)][string]$Directory,[Parameter(Mandatory=$true)][string]$Output)
$ErrorActionPreference='Stop'
function Read-Functions([string]$File) { $tokens=$null;$errors=$null;$ast=[System.Management.Automation.Language.Parser]::ParseFile($File,[ref]$tokens,[ref]$errors);if($errors.Count){throw ($errors|Out-String)};$records=@();foreach($f in $ast.FindAll({param($n)$n -is [System.Management.Automation.Language.FunctionDefinitionAst]},$true)){$bytes=[Text.Encoding]::UTF8.GetBytes(($f.Extent.Text -replace "`r`n","`n"));$sha=[Security.Cryptography.SHA256]::Create();try{$digest=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};$records+=@([ordered]@{name=$f.Name;bytes=$bytes.Length;sha256=$digest})};return ,$records }
$before=Read-Functions (Join-Path $Directory 'references/base-worker.ps1');$after=Read-Functions (Join-Path $Directory 'segment-worker.ps1');$changed=@();$same=@();foreach($b in $before){$a=@($after|Where-Object{$_.name -ceq $b.name});if($a.Count -ne 1){throw 'Missing/duplicate lifecycle function'};if($a[0].sha256 -ceq $b.sha256){$same+=@($b.name)}else{$changed+=@($b.name)}}
if(($changed -join '|') -cne 'Get-ReferenceWitnessPrimitive|Read-ReferenceWitnessProperty|Read-ReferenceWitnessPhase'){throw ('Unexpected lifecycle changes: '+($changed-join '|'))}
[ordered]@{before=$before;after=$after;unchanged=$same;changed=$changed;scope='Neutral function LF-normalized text hashes exact; executable bootstraps separately reviewed. No worker functions evaluated.';officeInvoked=$false} | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $Output -Encoding UTF8
Write-Output "Lifecycle functions $($same.Count)/$($before.Count) byteexact after LF normalization; exactly3 descriptor/primitive functions changed."
